export const captureSteps=[
 ['Preparar','Antes de tomar las fotos','Lava el auto y limpia los cristales. Estaciónalo en un lugar amplio, con luz uniforme y sin personas. Mantén la misma unidad, color, equipamiento y posición durante toda la sesión. Retira documentos y objetos personales.'],
 ['Exterior','Rodea el vehículo, una toma cada 10°','Recomendamos 36 fotos horizontales, mínimo 8. Empieza de frente (01) y avanza en sentido horario. Cámara a la altura de los faros, distancia constante y vehículo completo en cada toma. Bloquea enfoque, exposición y balance de blancos. No mezcles puertas abiertas con cerradas. Exporta a 1920–2560 px de ancho y numera 01…36.'],
 ['Interior 360°','Fotografía desde dentro, no desde la puerta','Necesitas una cámara 360° o una aplicación que exporte una esfera completa de 360° × 180°. Colócala en el centro de la zona delantera, a la altura de los ojos de una persona sentada; repite atrás. Usa un soporte fino, evita salir en la toma y mantén las puertas cerradas. Exporta JPG equirectangular 2:1, ideal 4096 × 2048. Una foto panorámica parcial del celular no sirve.'],
 ['Detalles','Acércate a lo que el comprador querrá ver','Toma fotografías normales del tablero encendido sin datos personales, pantalla, asientos, maletero y motor. Mantén buena luz y encuadres completos. Se mostrarán como fotos de detalle, no como panoramas. Puedes añadir hasta 8 vistas en total entre interior y detalles.'],
 ['Revisar','Recorre el vehículo antes de publicarlo','Prueba el giro exterior de principio a fin: no debe saltar ni cambiar de altura. Entra a cada panorama y mira techo, piso y uniones; evita costuras, desenfoque y personas. Comprueba nombres, puntos de navegación, zoom y pantalla ampliada. Guarda el vehículo al terminar.']
];
export function installCaptureGuide(section,node,getState){
 const body=section.querySelector('.tour-editor-body'),oldGuide=body.querySelector('details');oldGuide.hidden=true;const title=body.querySelector('h2');title.textContent='Crea su Torres 360, paso a paso';const nav=node('nav','capture-steps');nav.setAttribute('aria-label','Pasos de captura Torres 360');title.after(nav);const panels=captureSteps.map(([short,heading,copy],i)=>{const panel=node('section','capture-panel');panel.append(node('span','eyebrow',`PASO ${i+1} DE 5`),node('h3','',heading),node('p','',copy));body.append(panel);const button=node('button','',`${i+1}. ${short}`);button.type='button';button.onclick=()=>show(i);nav.append(button);return panel;});
 const externalInput=section.querySelector('#tour-exterior').closest('label'),externalList=section.querySelector('.tour-exterior-list');panels[1].append(externalInput,externalList);
 const fields=section.querySelector('#tour-scene-label').closest('.fields'),sceneUpload=section.querySelector('#tour-scene-file').closest('label'),sceneList=section.querySelector('.tour-scenes-list');panels[2].append(fields,sceneUpload,sceneList);
 const presets=node('div','capture-presets');panels[2].insertBefore(presets,fields);for(const name of ['Asientos delanteros','Asientos traseros']){const b=node('button','',`Preparar ${name.toLowerCase()}`);b.type='button';b.onclick=()=>{section.querySelector('#tour-scene-label').value=name;section.querySelector('#tour-scene-kind').value='panorama';};presets.append(b);}
 const detailPresets=node('div','capture-presets');for(const name of ['Tablero','Maletero','Motor','Asientos']){const b=node('button','',`Añadir ${name.toLowerCase()}`);b.type='button';b.onclick=()=>{show(2);section.querySelector('#tour-scene-label').value=name;section.querySelector('#tour-scene-kind').value='photo';section.querySelector('#tour-scene-label').focus();};detailPresets.append(b);}panels[3].append(detailPresets,node('p','','Estos accesos preparan el nombre y el tipo de foto en el paso de carga. Ahí seleccionas su archivo.'));
 const diagram=node('div','capture-diagram');diagram.innerHTML='<svg viewBox="0 0 480 280" role="img" aria-label="Rodea el auto en sentido horario: frente, lateral derecho, atrás y lateral izquierdo"><ellipse cx="240" cy="140" rx="180" ry="110" fill="none" stroke="#8294aa" stroke-dasharray="4 7"/><rect x="210" y="80" width="60" height="120" rx="15" fill="#495c73" stroke="#dce8f5"/><path d="M220 100h40v30h-40z" fill="#a5c5dd"/><g fill="#f5f7fa" text-anchor="middle" font-family="Arial" font-size="15"><text x="240" y="20">01 · Frente</text><text x="407" y="130">10 · Derecha</text><text x="240" y="270">19 · Atrás</text><text x="73" y="130">28 · Izquierda</text></g><path d="m386 54 20 22-30-1" fill="none" stroke="#f43459" stroke-width="4"/></svg>';panels[1].insertBefore(diagram,externalInput);
 const equipment=node('div','capture-kit');equipment.innerHTML='<strong>Equipo recomendado</strong><p>Exterior: celular o cámara, trípode y marcas en el suelo.<br>Interior: cámara 360°, soporte y disparo remoto.<br>Sin cámara 360°: puedes publicar exterior y detalles mientras preparas los panoramas.</p>';panels[0].append(equipment);const plan=node('div','capture-kit');plan.innerHTML='<strong>Tu sesión completa: 42 archivos</strong><ol><li>EX_01.jpg a EX_36.jpg: una vuelta exterior. 01 frente, 10 lateral derecho, 19 atrás, 28 lateral izquierdo.</li><li>IN_01_delante.jpg: esfera completa entre los asientos delanteros.</li><li>IN_02_atras.jpg: esfera completa en el centro de los asientos traseros.</li><li>DET_01_tablero.jpg, DET_02_pantalla.jpg, DET_03_maletero.jpg y DET_04_motor.jpg: fotos normales.</li></ol><p>Antes de hacer toda la sesión, prueba una panorámica interior: debe dejar mirar techo y piso sin huecos. Si solo tienes celular, empieza por el exterior y los detalles.</p>';panels[0].append(plan);
 const progress=node('div','capture-review');panels[4].append(progress);for(const text of ['Todas las imágenes son de este vehículo y corresponden a su estado actual.','He revisado el giro, las uniones y la nitidez de las panorámicas.','He comprobado que no se vean datos personales ni personas.']){const label=node('label','capture-check'),input=node('input');input.type='checkbox';label.append(input,node('span','',text));panels[4].append(label);}panels[4].append(section.querySelector('#tour-preview'),section.querySelector('.tour-admin-preview'));
 body.querySelectorAll(':scope>h3').forEach(h=>h.remove());const footer=node('div','capture-pagination'),previous=node('button','','Anterior'),next=node('button','','Continuar');previous.type=next.type='button';footer.append(previous,next);body.append(footer);let step=0;previous.onclick=()=>show(step-1);next.onclick=()=>show(step+1);
 function refresh(){const t=getState(),panos=t.scenes.filter(s=>s.kind==='panorama').length,photos=t.scenes.filter(s=>s.kind==='photo').length;progress.replaceChildren(node('strong','',`${t.exterior.length} fotos exteriores · ${panos} panoramas · ${photos} detalles`),node('p','',!t.exterior.length?'Sin giro exterior: se mostrarán solo las vistas cargadas.':t.exterior.length<36?'Giro exterior básico. Con 36 tomas se consigue una transición más suave.':'Secuencia exterior con 36 tomas o más.'),node('p','',panos<2?'Recorrido interior parcial: recomendamos una panorámica delantera y otra trasera.':'Revisa que los dos panoramas cubran realmente los asientos delanteros y traseros.'));}
 function show(i){step=Math.max(0,Math.min(4,i));panels.forEach((p,j)=>p.hidden=j!==step);[...nav.children].forEach((b,j)=>b.setAttribute('aria-current',j===step?'step':'false'));previous.disabled=step===0;next.hidden=step===4;refresh();}
 show(0);return{refresh,reset(){panels[4].querySelectorAll('input').forEach(i=>i.checked=false);show(0);}};
}
